/** Future native acceptance sources only. User's Java/build pause is still in force. */
@GameTestHolder("dynasty_army") @PrefixGameTestTemplate(false)
public final class BlindMarshalGameTests {
    private static final TicketType<UUID> TYPE=TicketType.create("dynasty_marshal_qa",UUID::compareTo);
    private record Ticket(ChunkPos chunk,UUID id){}
    private static final Map<ServerLevel,List<Ticket>> TICKETS=new HashMap<>();
    private static final Map<ServerLevel,List<Entity>> OWNED=new HashMap<>();
    private static final Map<ServerLevel,Set<Long>> YARDS=new HashMap<>();
    private static <T extends Entity>T own(GameTestHelper h,T e){OWNED.computeIfAbsent(h.getLevel(),k->new ArrayList<>()).add(e);return e;}
    @AfterBatch(batch="blind_marshal") public static void release(ServerLevel w){var es=OWNED.remove(w);if(es!=null)for(var e:es){if(e instanceof BlindMarshal m)for(var fx:m.effects())fx.discard();if(!e.isRemoved())e.discard();}var tickets=TICKETS.remove(w);if(tickets!=null)for(var t:tickets)w.getChunkSource().removeRegionTicket(TYPE,t.chunk(),2,t.id(),true);var yards=YARDS.remove(w);if(yards!=null){var s=MarshalCourtyardState.get(w);for(var key:yards)s.yards.remove(key);s.setDirty();}}
    private static BlindMarshal caster(GameTestHelper h){var origin=h.absolutePos(new BlockPos(8,1,8));var piece=new MarshalCourtyardPiece(origin);var box=piece.getBoundingBox();for(int x=(box.minX()-16)>>4;x<=(box.maxX()+16)>>4;x++)for(int z=(box.minZ()-16)>>4;z<=(box.maxZ()+16)>>4;z++){var ticket=new Ticket(new ChunkPos(x,z),UUID.randomUUID());h.getLevel().getChunkSource().addRegionTicket(TYPE,ticket.chunk(),2,ticket.id(),true);TICKETS.computeIfAbsent(h.getLevel(),k->new ArrayList<>()).add(ticket);var chunk=h.getLevel().getChunk(x,z);piece.postProcess(h.getLevel(),h.getLevel().structureManager(),h.getLevel().getChunkSource().getGenerator(),net.minecraft.util.RandomSource.create(11),new net.minecraft.world.level.levelgen.structure.BoundingBox(x*16,box.minY(),z*16,x*16+15,box.maxY(),z*16+15),chunk.getPos(),origin);}var yard=MarshalCourtyardState.get(h.getLevel()).register(piece.centre());YARDS.computeIfAbsent(h.getLevel(),k->new HashSet<>()).add(yard.centre.asLong());h.assertTrue(MarshalCourtyards.summon(h.getLevel(),yard),"Actual registered yard and central socket spawn one actor");var m=own(h,(BlindMarshal)h.getLevel().getEntity(yard.boss));m.setNoAi(true);return m;}
    private static Cow target(GameTestHelper h,BlindMarshal m,double x,double z){var c=own(h,EntityType.COW.create(h.getLevel()));c.moveTo(m.getX()+x,m.getY(),m.getZ()+z,0,0);c.setNoAi(true);c.setNoGravity(true);c.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);c.getAttribute(Attributes.KNOCKBACK_RESISTANCE).setBaseValue(1);c.setHealth(1000);h.getLevel().addFreshEntity(c);return c;}
    private static ServerPlayer player(GameTestHelper h,BlindMarshal m){var p=own(h,new ServerPlayer(h.getLevel().getServer(),h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"marshal-qa")));p.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(h.getLevel().getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p);p.setGameMode(GameType.SURVIVAL);p.moveTo(m.getX(),m.getY(),m.getZ()+8,0,0);p.setNoGravity(true);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);p.setHealth(1000);h.getLevel().addNewPlayer(p);h.onEachTick(p::doTick);return p;}
    @GameTest(template="cauldron_pit_test",timeoutTicks=225,batch="blind_marshal")
    public static void genuineFifteenMetreWallsOpenGateAndProtectedNineSecondIntro(GameTestHelper h){var m=caster(h);var p=m.arenaCentre();h.runAfterDelay(8,()->h.assertTrue(h.getLevel().getBlockState(p.offset(-16,14,0)).is(Blocks.SANDSTONE)&&h.getLevel().isEmptyBlock(p.offset(0,3,-16)),"Authored15m walls and7m wide gate, not a described-only arena"));h.runAfterDelay(179,()->h.assertTrue(m.intro()&&!m.hurt(m.damageSources().magic(),100),"Whole180tick intro protected"));h.runAfterDelay(184,()->{h.assertTrue(!m.intro()&&m.form()==1&&!m.noPhysics&&!m.isNoGravity(),"Grounded quadruped after intro");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=300,batch="blind_marshal")
    public static void twentyTellTicksThenRealPerimeterCurveAndFixedInwardTrample(GameTestHelper h){var m=caster(h);var c=target(h,m,0,8);var origin=m.position();h.runAfterDelay(184,()->h.assertTrue(m.startSkill(511,c),"Legal radius9 orbit starts"));h.runAfterDelay(203,()->h.assertTrue(m.phase()==AttackState.WINDUP&&m.position().distanceToSqr(origin)<.01&&c.getHealth()==1000,"Full20tick planted tell"));h.runAfterDelay(225,()->h.assertTrue(m.position().subtract(origin).horizontalDistance()>8.5&&c.getHealth()==1000,"Actual perimeter curve before inner cut"));h.runAfterDelay(257,()->{h.assertTrue(m.position().distanceToSqr(m.lockedPoint())<.03&&c.getHealth()<1000&&c.hasEffect(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN),"Collision-clipped inner cut reaches fixed floor point and tramples once");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=285,batch="blind_marshal")
    public static void realLowFiveMetreBladeDoesNotHitOverheadOrDoubleHitCloseBody(GameTestHelper h){var m=caster(h);var close=target(h,m,0,3.5);var far=target(h,m,0,8);var high=target(h,m,0,8);high.setPos(high.getX(),high.getY()+4,high.getZ());h.runAfterDelay(184,()->h.assertTrue(m.startSkill(512,far),"Sand slash begins"));h.runAfterDelay(199,()->h.assertTrue(close.getHealth()==1000&&far.getHealth()==1000,"No blade before16tick tell"));h.runAfterDelay(218,()->{h.assertTrue(close.getHealth()<1000&&close.getHealth()>=1000-16*1.2F-.01&&far.getHealth()<1000&&high.getHealth()==1000,"Actual down-pressed blade port reaches low near/far bodies, melee IDs excluded from same wave");h.assertTrue(m.effects().isEmpty(),"Five-metres and twelve-ticks bound wave life");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=305,batch="blind_marshal")
    public static void quietCrouchCannotTriggerButNativeJumpCueTriggersOneSafeTeleport(GameTestHelper h){var m=caster(h);var p=player(h,m);var origin=m.position();h.runAfterDelay(184,()->{p.setShiftKeyDown(true);h.assertTrue(m.startSkill(513,p),"Blind listening begins");});h.runAfterDelay(210,()->h.assertTrue(m.position().distanceToSqr(origin)<.01&&p.getHealth()==1000,"Quiet crouched actor provides no cue"));h.runAfterDelay(214,()->com.dynasty.blueprint.boss.BlindMarshalNoise.jump(new net.minecraftforge.event.entity.living.LivingEvent.LivingJumpEvent(p)));h.runAfterDelay(220,()->h.assertTrue(m.position().distanceToSqr(origin)>4&&p.getHealth()<1000&&m.cue()>=m.skillStart()&&!m.noPhysics,"Server jump cue produces legal loaded collision-checked counter and synchronized impact pose"));h.runAfterDelay(248,()->{h.assertTrue(p.getHealth()>=1000-16*1.4F-.01,"Only one counter within listening action");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=300,batch="blind_marshal")
    public static void twentyFourPhysicalWallArrowsAndFiniteExpiry(GameTestHelper h){var m=caster(h);var c=target(h,m,0,8);h.runAfterDelay(184,()->h.assertTrue(m.startSkill(514,c),"Wall volley begins"));h.runAfterDelay(207,()->h.assertTrue(m.effects().isEmpty(),"Full24tick tell"));h.runAfterDelay(209,()->h.assertTrue(m.effects().size()==24&&m.effects().stream().allMatch(e->e.kind()==MarshalProjectile.WALL_ARROW),"24real native arrows, not instant global damage"));h.runAfterDelay(279,()->{h.assertTrue(m.effects().isEmpty(),"All arrows bounded by60tick life/terrain contact");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=435,batch="blind_marshal")
    public static void halfHealthMorphSevenActualStepsAndSevenFiniteFloorCracks(GameTestHelper h){var m=caster(h);var c=target(h,m,0,9);var origin=m.position();h.runAfterDelay(184,()->m.setHealth(m.getMaxHealth()*.49F));h.runAfterDelay(188,()->h.assertTrue(m.form()==2&&m.transition(),"Half-health saved phase transition"));h.runAfterDelay(248,()->h.assertTrue(m.startSkill(515,c),"After60tick morph, seven-cut combo starts"));h.runAfterDelay(263,()->h.assertTrue(m.position().distanceToSqr(origin)<.01,"Full16tick combo tell"));h.runAfterDelay(319,()->h.assertTrue(Math.abs(m.position().subtract(origin).horizontalDistance()-5.25)<.05&&m.effects().stream().filter(e->e.kind()==MarshalProjectile.BLOOD_FISSURE).count()==7,"Seven real clipped.75m steps and7bounded source cracks"));h.runAfterDelay(420,()->{h.assertTrue(m.effects().isEmpty(),"Cracks expire within100ticks of creation");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=365,batch="blind_marshal")
    public static void stormSpendsLifeOnceThenTeleportAttacksAndClearsOnDeath(GameTestHelper h){var m=caster(h);var c=target(h,m,0,9);h.runAfterDelay(184,()->m.setHealth(m.getMaxHealth()*.49F));h.runAfterDelay(248,()->h.assertTrue(m.startSkill(516,c),"Phase2 storm begins"));h.runAfterDelay(275,()->h.assertTrue(m.stormActive()&&Math.abs(m.getHealth()-m.getMaxHealth()*.465F)<.01,"At24t cost2.5percent maximum life once, never a self-kill"));h.runAfterDelay(300,()->{h.assertTrue(c.getHealth()<1000&&m.stormActive(),"Native collision-checked storm teleport contacts target");m.hurt(m.damageSources().genericKill(),10000);h.assertTrue(!m.stormActive()&&m.effects().isEmpty(),"Death immediately ends scoped fog eligibility and finite effects");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=305,batch="blind_marshal")
    public static void heavyHitRetainsCooldownAndSavedTimeGapCannotReplayVolley(GameTestHelper h){var m=caster(h);var c=target(h,m,0,8);h.runAfterDelay(184,()->h.assertTrue(m.startSkill(512,c),"Tell begins"));h.runAfterDelay(188,()->{m.hurt(m.damageSources().magic(),60);h.assertTrue(m.phase()==AttackState.STUN&&!m.attack().ready(512,h.getLevel().getGameTime()),"30net heavy interrupt retains cooldown");});h.runAfterDelay(233,()->{h.assertTrue(m.startSkill(514,c),"Different skill begins after stun");var t=m.saveWithoutId(new CompoundTag());t.putLong("MarshalLastTick",h.getLevel().getGameTime()-25);m.load(t);});h.runAfterDelay(266,()->{h.assertTrue(m.skillId()==0&&m.effects().isEmpty()&&c.getHealth()==1000,"Time gap cancels without replaying24arrows");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=285,batch="blind_marshal")
    public static void unloadRetainsOneUuidThenConfirmedDeathPersistsFlowersAndRemoval(GameTestHelper h){var m=caster(h);var state=MarshalCourtyardState.get(h.getLevel());var yard=state.yards.get(m.arenaCentre().asLong());h.runAfterDelay(8,()->{var t=m.saveWithoutId(new CompoundTag());m.remove(Entity.RemovalReason.UNLOADED_TO_CHUNK);h.assertTrue(yard.boss!=null&&!yard.defeated&&!MarshalCourtyards.summon(h.getLevel(),yard),"Unload is reserved, never victory");var restored=own(h,BlindMarshalContent.MARSHAL.get().create(h.getLevel()));restored.load(t);restored.setNoAi(true);h.getLevel().addFreshEntity(restored);restored.hurt(restored.damageSources().genericKill(),10000);});h.runAfterDelay(12,()->{h.assertTrue(yard.defeated&&yard.boss==null&&!MarshalCourtyards.summon(h.getLevel(),yard),"Confirmed UUID death blocks natural repeat");for(int i=0;i<4;i++)MarshalCourtyards.applyEnvironment(h.getLevel(),yard,16);h.assertTrue(yard.environmentCursor==64&&h.getLevel().getBlockState(yard.centre.offset(13,-1,0)).is(Blocks.GRASS_BLOCK),"Actual authored ground flowers under persistent bounded cursor");var reload=MarshalCourtyardState.load(state.save(new CompoundTag()));h.assertTrue(reload.yards.get(yard.centre.asLong()).defeated,"Victory survives SavedData NBT");});h.runAfterDelay(255,()->{h.assertTrue(h.getLevel().getEntitiesOfClass(BlindMarshal.class,new AABB(yard.centre).inflate(20)).isEmpty(),"240tick death removes once");h.succeed();});}
}
